const body = $json.body;
if (!body || typeof body !== 'object') throw new Error('Dados da escala ausentes.');
const validDate = value => /^\d{4}-\d{2}-\d{2}$/.test(value || '') &&
    !Number.isNaN(Date.parse(value)) && new Date(value).toISOString().slice(0,10) === value;
if (!validDate(body.data_escala)) throw new Error('Data inválida.');
if (!body.save_request_id || !/^[\w-]{8,100}$/.test(body.save_request_id)) throw new Error('Identificador do envio inválido.');
if (!body.json_turnos || Array.isArray(body.json_turnos) || typeof body.json_turnos !== 'object') throw new Error('Turnos ausentes.');
if (!body.json_layout || !Array.isArray(body.json_layout.turnos) || !Array.isArray(body.json_layout.tabelas)) throw new Error('Layout ausente.');
const parse = (value, fallback) => typeof value === 'string' ? JSON.parse(value) : value || fallback;
const normalize = n => String(n).normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();
const allocated = new Set();
const add = value => {
    String(value || '').split(',').filter(n=>n.trim()).forEach(n=> {
        const key=normalize(n); if (allocated.has(key)) throw new Error('Colaborador duplicado: '+n);
        allocated.add(key);
    });
};
for (const [id,names] of Object.entries(body.json_turnos)) {
    if (!/^t_[a-zA-Z0-9_-]+$/.test(id) || typeof names !== 'string') throw new Error('Turno inválido.');
    add(names);
}
add(body.folgas);
String(body.fiscais || '').split('||').filter(Boolean).forEach(row => add(row.split('|')[0]));
const extra = parse(body.json_tabelas_extras, {});
for (const table of body.json_layout.tabelas) {
    if (!/^tbl_[a-zA-Z0-9_-]+$/.test(table.id) || !Array.isArray(table.colunas) || !table.colunas.length) throw new Error('Tabela inválida.');
    if (!Array.isArray(extra[table.id] || [])) throw new Error('Linhas inválidas.');
    for (const row of extra[table.id] || []) add(row[table.colunas[0]]);
}
for (const turno of body.json_layout.turnos) {
    if (!/^t_[a-zA-Z0-9_-]+$/.test(turno.id)) throw new Error('ID de turno inválido.');
}
if (body.expected_updated_at && Number.isNaN(Date.parse(body.expected_updated_at))) throw new Error('Versão base inválida.');
const exceptions = parse(body.json_excecoes_horario, []);
if (!Array.isArray(exceptions)) throw new Error('Exceções inválidas.');
return [{json: {...$json, body: {...body,
    json_excecoes_horario:JSON.stringify(exceptions), json_tabelas_extras:JSON.stringify(extra)}}}];

const b=$json.body;
if (!b || !Array.isArray(b.cfg_turnos) || !Array.isArray(b.cfg_tabelas_extras) || !Array.isArray(b.cfg_fiscais_padrao) || !Array.isArray(b.cfg_excecoes_padrao)) throw new Error('Configuração inválida.');
const ids=new Set();
for (const item of [...b.cfg_turnos,...b.cfg_tabelas_extras]) {
    if (!/^(t|tbl)_[a-zA-Z0-9_-]+$/.test(item.id || '') || ids.has(item.id)) throw new Error('Identificador inválido ou repetido.');
    ids.add(item.id);
}
for (const table of b.cfg_tabelas_extras) if (!Array.isArray(table.colunas) || !table.colunas.length || table.colunas.some(c=>typeof c!=='string')) throw new Error('Colunas inválidas.');
if (!Number.isInteger(b.max_folgantes) || b.max_folgantes < 0) throw new Error('Limite inválido.');
for (const key of ['cor_primaria','cor_secundaria','cor_alerta']) if (!/^#[0-9a-f]{6}$/i.test(b[key] || '')) throw new Error('Cor inválida.');
return [{json:$json}];

